import React, { useState, useEffect } from "react";
import axios from "axios";
import QuestionCard from "./component/QuestionCard";
import "./App.css";

function App() {
  const [masterQuestionList, setMasterQuestionList] = useState([]);
  const [isPrivacyToggled, setIsPrivacyToggled] = useState(false);

  const createInitialForm = () => Array(5).fill(null).map(() => ({ 
    selectedQuestion: "", 
    userAnswer: "", 
    answerConfirmation: "" 
  }));

  const [formRows, setFormRows] = useState(createInitialForm());

  useEffect(() => {
    axios.get("http://localhost:3001/questions")
      .then((res) => {
        // Ensure res.data is actually an array before setting state
        setMasterQuestionList(Array.isArray(res.data) ? res.data : []);
      })
      .catch((err) => {
        console.error("Connection failed:", err);
        setMasterQuestionList([]); // Fallback to empty array
      });
  }, []);

  const handleFieldUpdate = (index, key, value) => {
    const updatedRows = [...formRows];
    updatedRows[index][key] = value;
    setFormRows(updatedRows);
  };

  const getFilteredQuestions = (currentIndex) => {
    const usedInOtherBoxes = formRows
      .filter((_, idx) => idx !== currentIndex)
      .map(row => row.selectedQuestion);

    return masterQuestionList.filter(item => !usedInOtherBoxes.includes(item.question));
  };

  const submitForm = async () => {
    const isComplete = formRows.every(r => r.selectedQuestion && r.userAnswer && r.answerConfirmation);
    const isMatched = formRows.every(r => r.userAnswer === r.answerConfirmation);

    if (!isComplete) return alert("Please fill all 5 sections.");
    if (!isMatched) return alert("Answers do not match.");

    try {
      await axios.post("http://localhost:3001/responses", { responses: formRows });
      alert("Success!");
      setFormRows(createInitialForm());
    } catch (err) {
      alert("Submission Error");
    }
  };

  return (
    <div className="app-container">
      <div className="privacy-control">
        <label>
          <input 
            type="checkbox" 
            checked={isPrivacyToggled} 
            onChange={() => setIsPrivacyToggled(!isPrivacyToggled)} 
          />
          Hide Answers
        </label>
      </div>

      <h1 className="main-title">Security Settings</h1>

      <div className="form-wrapper">
        {formRows.map((data, i) => (
          <QuestionCard
            key={i}
            index={i}
            rowData={data} // Passing as 'rowData'
            options={getFilteredQuestions(i)}
            shouldMask={isPrivacyToggled} 
            onUpdate={handleFieldUpdate}
          />
        ))}

        <button className="submit-btn" onClick={submitForm}>
          Save All Changes
        </button>
      </div>
    </div>
  );
}

export default App;
